class Solution:
    def __init__(self):
        self.buf4 = [''] * 4
        self.i = 0
        self.cnt = 0

    def read(self, buf: List[str], n: int) -> int:
        total = 0
        while total < n:
            if self.i == self.cnt:
                self.i = 0
                self.cnt = read4(self.buf4)
                if self.cnt == 0:
                    break
            buf[total] = self.buf4[self.i]
            self.i += 1
            total += 1
        return total

