from collections import deque

class Solution:
    def __init__(self):
        self.q = deque()

    def read(self, buf: List[str], n: int) -> int:
        total = 0
        while total < n:
            if not self.q:
                tmp = [''] * 4
                k = read4(tmp)
                if k == 0:
                    break
                for j in range(k):
                    self.q.append(tmp[j])
            buf[total] = self.q.popleft()
            total += 1
        return total

