class Solution {
    queue<char> q;
public:
    int read(char *buf, int n) {
        int total = 0;
        while (total < n) {
            if (q.empty()) {
                char tmp[4];
                int k = read4(tmp);
                if (k == 0) break;
                for (int j = 0; j < k; ++j) q.push(tmp[j]);
            }
            buf[total++] = q.front(); q.pop();
        }
        return total;
    }
};

