import java.util.*;

public class Solution extends Reader4 {
    private Deque<Character> q = new ArrayDeque<>();

    public int read(char[] buf, int n) {
        int total = 0;
        while (total < n) {
            if (q.isEmpty()) {
                char[] tmp = new char[4];
                int k = read4(tmp);
                if (k == 0) break;
                for (int j = 0; j < k; ++j) q.add(tmp[j]);
            }
            buf[total++] = q.poll();
        }
        return total;
    }
}

